const items = $input.all();
if (!items || items.length === 0) return [];
const threadMap = new Map();
for (const item of items) {
  const msg = item.json;
  const threadId = msg.threadId;
  if (!threadId) continue;
  const msgDate = parseInt(msg.internalDate || '0', 10);
  const labelNames = (msg.labels || []).map(l => typeof l === 'string' ? l : (l.name || '')).filter(Boolean);
  const existing = threadMap.get(threadId);
  if (!existing) {
    threadMap.set(threadId, { thread_id: threadId, message_id: msg.id, date: msgDate, subject: msg.Subject || msg.subject || '(no subject)', from: msg.From || msg.from || '', to: msg.To || msg.to || '', snippet: msg.snippet || '', labels: labelNames });
  } else {
    // Always merge labels from all messages in thread
    existing.labels = [...new Set([...existing.labels, ...labelNames])];
    // Keep newest message's metadata
    if (msgDate > existing.date) {
      existing.message_id = msg.id;
      existing.date = msgDate;
      existing.subject = msg.Subject || msg.subject || existing.subject;
      existing.from = msg.From || msg.from || existing.from;
      existing.to = msg.To || msg.to || existing.to;
      existing.snippet = msg.snippet || existing.snippet;
    }
  }
}
const results = [];
for (const [, thread] of threadMap) results.push({ json: thread });
return results;

const parseItems = $('Parse & Deduplicate Threads').all();
const threadItems = $input.all();
const results = [];
for (let i = 0; i < threadItems.length; i++) {
  const threadData = threadItems[i].json;
  const parseData = parseItems[i]?.json || {};
  const msgCount = (threadData.messages || []).length;
  // Collect ALL labelIds from ALL messages in thread (including read ones)
  const allLabelIds = new Set();
  for (const msg of (threadData.messages || [])) {
    for (const lid of (msg.labelIds || [])) allLabelIds.add(lid);
  }
  if (msgCount >= 3) {
    results.push({ json: { ...parseData, _msg_count: msgCount, _thread_label_ids: [...allLabelIds] } });
  }
}
return results.length > 0 ? results : [];

const items = $input.all();
const results = [];
const internalDomains = ['dadsprinting.com', 'proteamjerseys.com'];
for (const item of items) {
  const data = item.json;
  const fromRaw = data.from || '';
  const emailMatch = fromRaw.match(/<([^>]+)>/);
  const senderEmail = emailMatch ? emailMatch[1].toLowerCase() : fromRaw.toLowerCase().trim();
  if (!senderEmail) continue;
  const domain = senderEmail.split('@')[1] || '';
  if (internalDomains.includes(domain)) continue;
  const nameMatch = fromRaw.match(/^"?([^"<]+)"?\s*</);
  const senderName = nameMatch ? nameMatch[1].trim() : senderEmail.split('@')[0];
  results.push({ json: { sender_email: senderEmail, sender_name: senderName, subject: data.subject || '(no subject)', date: data.date || '', thread_id: data.thread_id, message_id: data.message_id, snippet: data.snippet || '', labels: data.labels || [], _thread_label_ids: data._thread_label_ids || [], _msg_count: data._msg_count || 0 } });
}
return results.length > 0 ? results : [];

const MAX_DRAFTS_PER_THREAD = 1;
const COOLDOWN_MS = 6 * 60 * 60 * 1000; // 6 hours
const now = Date.now();
const incomingItems = $('Extract Sender & Thread Info').all();
if (!incomingItems || incomingItems.length === 0) return [];
const sheetRows = $input.all();

// Build a map: thread_id -> { count, latestTime }
const threadMap = new Map();
for (const row of sheetRows) {
  const tid = row.json?.thread_id;
  if (!tid) continue;
  const processedAt = row.json?.processed_at ? new Date(row.json.processed_at).getTime() : 0;
  if (!threadMap.has(tid)) threadMap.set(tid, { count: 0, latestTime: 0 });
  const entry = threadMap.get(tid);
  entry.count++;
  if (processedAt > entry.latestTime) entry.latestTime = processedAt;
}

const newItems = incomingItems.filter(item => {
  const tid = item.json.thread_id;
  const entry = threadMap.get(tid);
  if (!entry) return true; // Never drafted — allow
  // If last draft was within cooldown window, skip
  if ((now - entry.latestTime) < COOLDOWN_MS) return false;
  // If cooldown expired, allow a new draft (customer likely replied)
  return true;
});
return newItems.length > 0 ? newItems : [];

const enrichedItems = $input.all();
const stashedItems = $('Stash Thread Meta').all();
return enrichedItems.map((item, idx) => {
  const threadMeta = stashedItems[idx]?.json?._thread_meta || {};
  return { json: { ...threadMeta, enriched: item.json } };
});

const items = $input.all();
const preparedItems = $('Prepare Image Data').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const classifyResp = items[i].json;
  const data = preparedItems[i]?.json || {};
  const enriched = data.enriched || {};
  const identity = enriched.identity || {};
  const deals = enriched.deals || [];
  const dealContext = enriched.deal_context || null;
  const order = enriched.order || null;
  const financials = enriched.financials || null;
  const thread = enriched.thread || null;

  // Check both label names AND thread-level label IDs
  // Label_6992024041184135133 = TAG-SYS/Sales/NEEDS-INFO
  const NEEDS_INFO_LABEL_ID = 'Label_6992024041184135133';
  const isNeedsInfo = (data.labels || []).some(l => {
    const label = typeof l === 'string' ? l.toLowerCase() : '';
    return label.includes('needs-info') || label.includes('needs_info');
  }) || (data._thread_label_ids || []).includes(NEEDS_INFO_LABEL_ID);

  let category = 'general';
  if (!isNeedsInfo) {
    try {
      const rawCat = (classifyResp.content?.[0]?.text || 'general').trim().toLowerCase();
      const valid = ['pricing_inquiry','order_status','quote_followup','capability_question','complaint','artwork_proof','general'];
      category = valid.includes(rawCat) ? rawCat : 'general';
    } catch(e) {}
  } else {
    category = 'needs_info_assessment';
  }

  const senderName = data.sender_name || identity.name || 'there';
  const firstName = senderName.split(' ')[0];

  let context = '';
  if (identity.name) context += 'Contact: ' + identity.name;
  if (identity.org_name) context += ' @ ' + identity.org_name;
  if (identity.new_contact) context += ' [NEW CONTACT - not in Pipedrive]';
  context += '\n';
  if (deals.length > 0) {
    context += '\nActive deals:\n';
    for (const d of deals) {
      context += '- ' + d.title + ' | Stage: ' + d.stage;
      if (d.value) context += ' | Value: $' + d.value;
      if (d.quantity) context += ' | Qty: ' + d.quantity;
      if (d.deadline) context += ' | Deadline: ' + d.deadline;
      if (d.item_of_interest) context += ' | Item: ' + d.item_of_interest;
      context += ' | Owner: ' + (d.owner || 'Unassigned') + '\n';
    }
  }
  if (dealContext && dealContext.content) {
    context += '\n=== FULL DEAL HISTORY ===\n' + dealContext.content + '\n=== END DEAL HISTORY ===\n';
  }
  if (order && order.found_on_board) {
    context += '\nOrder status: ' + order.found_on_board;
    if (order.item_name) context += ' - ' + order.item_name;
    if (order.human_readable) context += '\n' + order.human_readable;
    if (order.eta) context += '\nETA: ' + order.eta;
    context += '\n';
  }
  if (financials && financials.outstanding_balance > 0) {
    context += '\nFinancials: Outstanding $' + financials.outstanding_balance;
    if (financials.open_invoices?.length > 0) {
      context += ' | Invoices: ' + financials.open_invoices.map(inv => '#' + (inv.doc_number||'?') + ' ($' + inv.amount + ')').join(', ');
    }
    context += '\n';
  }
  let threadSummary = '';
  if (thread?.summary) threadSummary = '\nThread summary (' + (thread.message_count||'?') + ' messages):\n' + thread.summary + '\n';

  let systemPrompt, userPrompt;

  if (isNeedsInfo) {
    systemPrompt = 'You are a quote-readiness assessor for Dad\'s Printing, a custom apparel company in Vancouver, BC.\n\nThe customer submitted an inquiry and was asked for more information. They have now replied. Assess what quote-critical information has been provided across ALL sources (reply, deal history, form data, attachments) and determine if enough info exists to generate a quote.\n\nIMPORTANT: Always stitch together information from ALL sources. The snippet may only contain the latest reply, but DEAL HISTORY may have quantity, garment type, artwork status, etc. from earlier calls, forms, or notes. Combine everything before making your assessment.\n\nIf the customer corrects or changes something from the original form or earlier conversation (e.g., form said screenprint but customer now says embroidery), ALWAYS respect the customer\'s latest statement over older data.\n\nCRITICAL INFERENCE RULE: Customers do NOT use industry terminology. Accept natural language answers and infer the meaning. Examples:\n- "softness is most important" = bamboo material. Do NOT ask them to confirm bamboo.\n- "just logo on front and number on back" = NOT all-over print. Do NOT ask them to confirm it is not all-over.\n- "I have the logo ready" or "logo designed already" = artwork is available. Do NOT ask for the file again.\n- "fully sublimated with all-over print" = sublimation service type. Do NOT reclassify as jerseys or digital.\n- "printed, not stitched" = printed graphics. Do NOT re-ask.\n- "red and black" = colorway provided. Do NOT ask for colorway confirmation.\nIf you can reasonably infer the answer from what was said, treat it as provided. Only mark something as MISSING if there is genuinely no information about it anywhere in the sources.\n\nQUOTE-READINESS CRITERIA BY SERVICE TYPE:\n\n--- AUTO-QUOTABLE SERVICE TYPES (AUTO_QUOTABLE=YES when complete) ---\n\nSCREENPRINT:\nRequired: quantity (exact or range), garment type OR supplying own blanks, number of print colors OR artwork provided, print location(s)\nNote: Does NOT need to be explicitly called screenprint. If context suggests it (design type, quantity, description), infer it.\n\nEMBROIDERY:\nRequired: must be confirmed or obviously embroidery, quantity (exact or range), garment type OR supplying own blanks, stitch count range OR artwork/logo provided, embroidery location(s)\n\nDIGITAL:\nRequired: quantity (exact or range), garment type, artwork or design provided/described, approximate print dimensions\nSize tiers for pricing: left chest ~4x4, small center ~8x8, standard center ~10x10, large front up to ~14x16. Exact measurements not required.\n\nPATCHES:\nRequired: quantity (exact or range), patch size, patch type (woven/embroidered/PVC/chenille or not sure), artwork provided\nOptional: raised edge yes/no ($0.25/unit upsell opportunity)\n\n--- MANUAL-QUOTE SERVICE TYPES (AUTO_QUOTABLE=NO always, even when complete) ---\n\nThese types are quoted by Adam personally. The bar for QUOTE_READY=YES is lower — you just need enough info for Adam to build a quote, not every micro-detail. If you can tell what they want, how many, and have a general sense of the spec, that is QUOTE_READY=YES.\n\nSUBLIMATION:\nRequired: quantity (exact or range), item type (jerseys, performance wear, etc.), any special features mentioned\nAUTO_QUOTABLE: always NO\n\nJERSEYS:\nRequired: quantity (exact or range), stitched or printed graphics, desired colorway, all-over print OR just logo+number (infer from description — if they describe specific graphic placements like "logo front, number back" that means NOT all-over), names and numbers on back (yes/no)\nAUTO_QUOTABLE: always NO\n\nSOCKS:\nRequired: quantity (exact or range), desired material OR priority feature (infer: softness=bamboo, durability=cotton, soft+durable=combed cotton, all-over print=sublimation), graphic/design description or artwork\nAUTO_QUOTABLE: always NO\n\nPROMO PRODUCTS:\nRequired: quantity (exact or range), specific product identified (water bottles, pens, mugs, etc.), graphics/branding, color of item, any features vital to the item\nAUTO_QUOTABLE: always NO\n\nQUANTITY RULES:\n- Exact number or a range (e.g., 50-75) is fine — quote to the higher end for better per-unit pricing\n- Vague quantities like "a few dozen" or "some" or "depends on pricing" are NOT quotable — ask for at least a rough range\n\nRESPONSE FORMAT (follow exactly):\nQUOTE_READY: YES or NO\nSERVICE_TYPE: screenprint or embroidery or digital or patches or sublimation or jerseys or socks or promo or unknown\nMISSING: comma-separated list of still-missing items, or none\nAUTO_QUOTABLE: YES or NO\n---\n[Draft email reply here]\n\nDRAFT RULES:\n- If QUOTE_READY=NO: Acknowledge what they DID provide specifically. Ask ONLY for what is still missing. Be conversational not like a checklist.\n- If QUOTE_READY=YES: Acknowledge their info warmly, tell them you are putting their quote together now.\n- Start with "Hey ' + firstName + ',"\n- Sign off as just "Adam"\n- 2-4 sentences max\n- NEVER make up prices or timelines\n- If they provided an image or design, acknowledge it\n- Check ALL sources (snippet, thread summary, deal history) before claiming something is missing';

    userPrompt = 'Context:\n' + context + threadSummary + '\nLatest snippet: "' + (data.snippet || '') + '"\nSubject: "' + (data.subject || '') + '"\n\nAssess quote readiness and write a draft reply.';
  } else {
    const categoryInstructions = {
      pricing_inquiry: 'This is a PRICING INQUIRY. The customer wants a quote or pricing info. ONLY ask for what is genuinely missing. If they told you the product type, acknowledge it. If they shared a design or image, say "got the design" — do not ask them to describe it. Typical missing info: quantity, sizes, whether they supply blanks or we do. Do NOT make up prices. If they gave enough detail to quote, say you are working on pricing now. CHECK THE DEAL HISTORY — if previous notes/calls already captured product type, quantity, or artwork, do NOT ask for them again.',
      order_status: 'This is an ORDER STATUS request. Use the order context above to give them a real update. If no order data exists, say you will check with the team.',
      quote_followup: 'This is a QUOTE FOLLOW-UP. Be encouraging but not pushy. Reference the deal stage if available. If deal history shows what was quoted, reference it specifically.',
      capability_question: 'This is a CAPABILITY QUESTION. Be confident about what Dad\'s Printing can do (screenprint, embroidery, DTG, sublimation, patches, promo products, custom socks).',
      complaint: 'This is a COMPLAINT. Lead with empathy. Acknowledge the specific issue. Say you are looking into it personally.',
      artwork_proof: 'This is about ARTWORK or PROOFS. Acknowledge what they sent. If they attached files or images, confirm receipt. Give next steps.',
      general: 'This is a GENERAL email. Respond helpfully based on the context. Keep it brief and direct.'
    };

    const baseSystem = 'You are a rep at Dad\'s Printing, a custom apparel company in Vancouver, BC. Voice: brief, direct, friendly. Use first names. Sign off as just "Adam". No formal language. 2-4 sentences max. NEVER make up prices, timelines, or details you don\'t have.\n\nCRITICAL ANTI-REDUNDANCY RULES:\n- Before asking ANY question, check the snippet, thread summary, AND deal history. If the customer already answered it in ANY of these sources, do NOT ask again.\n- If they said what product they want, acknowledge it — do not ask "what type of items are you looking for?"\n- If they shared a design, image, or artwork, acknowledge it — never ask them to describe what they already showed you.\n- If they gave a quantity, do not ask for quantity.\n- If the DEAL HISTORY shows info from a previous call or note (quantity, product type, timeline), treat that as known — do not re-ask.\n- If they asked "how much would it cost", acknowledge and ask ONLY for missing variables (typically: quantity, sizes, blanks).\n- The goal is a draft Adam can send without editing.\n- If the email mentions an attachment you cannot see, acknowledge it exists.\n\nIMAGE AWARENESS:\n- If the customer attached an image and it is included below, you CAN see it.\n- Briefly describe what you observe (e.g., "got the design — looks like a single-color back print on a white tee") and use it to ask smarter questions.\n- Do NOT ask the customer to describe something you can already see.\n- Use visual details to identify: product type, print method, number of colors, print locations, complexity.\n- If the image shows text on a garment, note the text content.';

    systemPrompt = baseSystem + '\n\n' + categoryInstructions[category];
    userPrompt = 'Context:\n' + context + threadSummary + '\nLatest snippet: "' + (data.snippet || '') + '"\nSubject: "' + (data.subject || '') + '"\n\nWrite a draft reply. Start with "Hey ' + firstName + '," and end with just "Adam".';
  }

  const warnings = [];
  const snippetLower = (data.snippet || '').toLowerCase() + ' ' + (thread?.summary || '').toLowerCase();
  if (category === 'complaint') warnings.push('COMPLAINT - review carefully before sending');
  if (/\$\d/.test(data.snippet || '')) warnings.push('Customer mentioned a dollar amount - verify pricing');
  if (/urgent|asap|rush|emergency/i.test(snippetLower)) warnings.push('URGENT tone detected');
  if (financials && financials.outstanding_balance > 500) warnings.push('Outstanding balance > $500: $' + financials.outstanding_balance);
  if (identity.new_contact) warnings.push('NEW CONTACT - not yet in Pipedrive');
  if (dealContext) warnings.push('Deal history available — draft informed by ' + dealContext.source);
  if (isNeedsInfo) warnings.push('NEEDS-INFO assessment — checking quote readiness');

  let messageContent;
  if (data._has_image && data._image_base64 && data._image_mime) {
    messageContent = [
      { type: 'image', source: { type: 'base64', media_type: data._image_mime, data: data._image_base64 } },
      { type: 'text', text: userPrompt }
    ];
  } else {
    messageContent = userPrompt;
  }

  const requestBody = { model: 'claude-haiku-4-5-20251001', max_tokens: 1024, system: systemPrompt, messages: [{ role: 'user', content: messageContent }] };

  const dealId = deals.length > 0 ? deals[0].id : null;

  results.push({ json: { ...data, _category: category, _warnings: warnings, _ai_request_body: requestBody, _is_needs_info: isNeedsInfo, _deal_id: dealId } });
}
return results;

const items = $input.all();
const buildItems = $('Build Classified Draft Prompt').all();
const results = [];

const SIGNATURE_HTML = '<div dir="ltr" class="gmail_signature" data-smartmail="gmail_signature"><div dir="ltr"><table cellpadding="0" cellspacing="0" border="0" style="color:rgb(0,0,0);font-family:Montserrat,sans-serif;font-size:medium;max-width:500px;width:500px;border-collapse:collapse"><tbody><tr><td style="padding:10px"><table cellpadding="0" cellspacing="0" border="0" style="width:480px;border-collapse:collapse"><tbody><tr><td width="100" valign="top"><img src="https://ci3.googleusercontent.com/meips/ADKq_NafwbmhMrK-WpXLK5WIDkS5a3zKMaOdR89JejvSLrHGQk2na2s7p5v-MxA1Tl8CiGBOvmblgkMn8m2Xq83uHbEFNUrQNoE6XSsIo4R0ObO8g1YiixuyfNgw-MB48tYo=s0-d-e1-ft#https://sigimg.com/host/artbrush/5000/5100/5090.adamlando604/Headshot.png" alt="Adam Lando" width="100" height="100" style="border-radius:8px;display:block"></td><td width="15"></td><td valign="middle" style="border-left:2px solid rgb(170,0,0);padding-left:15px"><div style="color:rgb(170,0,0);font-weight:600;font-size:16px;text-transform:uppercase">Adam Lando</div><div style="font-size:13px;margin-top:4px"><img src="https://ci3.googleusercontent.com/meips/ADKq_Nb8O0buRrAH8-ssCH2J0S173b9qoOz_QwRjz6wWMsH92sTZpRiWWVmgPCTXV5WETRqf6LCkI26ItHSUD1TFEMof9B0gFmKVXOKavR_BXQI6l3eZWDdD971rudo=s0-d-e1-ft#https://sigimg.com/host/artbrush/5000/5100/5090.adamlando604/call.png" alt="Call" width="14" style="vertical-align:middle;margin-right:6px">&nbsp;<a href="tel:1-833-879-3237+EXT+700" style="color:rgb(0,0,0)" target="_blank">1-833-879-3237 EXT 700</a></div><div style="font-size:13px;margin-top:4px"><img src="https://ci3.googleusercontent.com/meips/ADKq_NaHnm6Gy4DAbG4jGTvfP6ev8KXGK9PE8lSwRgLy4b9l6kn6EJ_K5EY-CuHj0QTir0wnpvDrkIJnsRsszl8OYheUt7wPZVowUmf1KqmsVPHyKvlURqpLfPJlbeqK=s0-d-e1-ft#https://sigimg.com/host/artbrush/5000/5100/5090.adamlando604/email.png" alt="Email" width="14" style="vertical-align:middle;margin-right:6px">&nbsp;<a href="mailto:info@dadsprinting.com" style="color:rgb(0,0,0)" target="_blank">info@dadsprinting.com</a></div></td></tr></tbody></table><div style="height:15px"></div><table cellpadding="0" cellspacing="0" border="0" style="width:480px;border-collapse:collapse;border:1.5px solid rgb(170,0,0);border-radius:6px"><tbody><tr><td style="padding:10px"><table cellpadding="0" cellspacing="0" border="0" style="width:457px;border-collapse:collapse"><tbody><tr><td style="padding:0px;vertical-align:middle"><img src="https://ci3.googleusercontent.com/meips/ADKq_NZltuSyX9zYJvKyFEGu2pTIF4ATV08RBnfBu_lqiR65jAr962Nm7RqskdiFiDQxnBt9vAvg75ZMWmregggoi-za30PBaJ5m__Jp0ZlTfZGf9Idt8ucuOaoUJNT6TvvjRqR4XR8pzhYNZBKgqBhs5WuWRICJBw=s0-d-e1-ft#https://www.dadsprinting.com/wp-content/uploads/2025/04/cropped-Staple_Logo_Main_Colorway-1.png" alt="Dad&#39;s Printing" width="100" style="display:block"></td><td style="padding:0px 0px 0px 10px;vertical-align:middle"><a href="https://calendly.com/dads-printing/appointment" target="_blank"><img src="https://ci3.googleusercontent.com/meips/ADKq_Nawgke4KBbIYgUsb95-RwpxStevHRa74vPC59MQJusyAQ0rtcPjnBhuTvJ83E8gadUFUYY_GrIDdY0MXBZcZrvUK6HJL2iTc1L6y3mcHYal7blTqcnvsn1Kibjb=s0-d-e1-ft#https://sigimg.com/host/artbrush/5000/5100/5090.adamlando604/sbtn3.png" alt="Book a Meeting" width="170" height="22" style="display:block;border:none"></a></td></tr></tbody></table></td></tr></tbody></table><div style="height:10px"></div><table width="100%" border="0" cellspacing="0" cellpadding="0"><tbody><tr><td valign="right" style="text-align:left;font-family:Montserrat,Arial,sans-serif;font-size:8pt;line-height:12.8px;color:rgb(128,128,128)"><a href="https://www.dadsprinting.com/unsubscribe/">Unsubscribe</a></td></tr></tbody></table></td></tr></tbody></table></div></div>';

for (let i = 0; i < items.length; i++) {
  const response = items[i].json;
  const meta = buildItems[i] ? buildItems[i].json : {};
  const warnings = meta._warnings || [];
  const category = meta._category || 'general';
  const isNeedsInfo = meta._is_needs_info || false;

  let draftText = '';
  let draftFailed = false;
  if (response.content && Array.isArray(response.content)) {
    draftText = response.content.filter(c => c.type === 'text').map(c => c.text).join('\n');
    if (!draftText || draftText.trim().length === 0) draftFailed = true;
  } else {
    draftFailed = true;
  }

  if (draftFailed) continue;

  let quoteReady = false;
  let autoQuotable = false;
  let serviceType = 'unknown';
  let missingItems = '';

  if (isNeedsInfo) {
    const lines = draftText.split('\n');
    const dividerIdx = lines.findIndex(l => l.trim() === '---');
    if (dividerIdx > 0) {
      for (let li = 0; li < dividerIdx; li++) {
        const line = lines[li].trim();
        if (line.startsWith('QUOTE_READY:')) quoteReady = line.split(':')[1].trim().toUpperCase() === 'YES';
        if (line.startsWith('SERVICE_TYPE:')) serviceType = line.split(':')[1].trim().toLowerCase();
        if (line.startsWith('MISSING:')) missingItems = line.substring(line.indexOf(':') + 1).trim();
        if (line.startsWith('AUTO_QUOTABLE:')) autoQuotable = line.split(':')[1].trim().toUpperCase() === 'YES';
      }
      draftText = lines.slice(dividerIdx + 1).join('\n').trim();
    }
  }

  // Build subject prefix with all review info (no HTML banners in body)
  const subjectTags = [];
  if (isNeedsInfo) {
    if (quoteReady) {
      subjectTags.push('QUOTE READY - ' + serviceType.toUpperCase() + (autoQuotable ? ' - AUTO' : ' - MANUAL'));
    } else {
      subjectTags.push('NEEDS-INFO: ' + (missingItems || 'check draft'));
    }
  }
  if (category === 'complaint') subjectTags.push('COMPLAINT');
  if (warnings.some(w => w.includes('URGENT'))) subjectTags.push('URGENT');
  if (warnings.some(w => w.includes('Outstanding balance'))) subjectTags.push('$$');
  if (warnings.some(w => w.includes('NEW CONTACT'))) subjectTags.push('NEW');
  // Always show category
  if (!isNeedsInfo) subjectTags.push(category.replace('_', ' ').toUpperCase());

  const subjectPrefix = subjectTags.length > 0 ? '[' + subjectTags.join(' | ') + '] ' : '';

  // Clean HTML body — just the draft text + signature, nothing else
  const htmlDraft = draftText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n\n/g, '</p><p style="margin:0 0 12px;">').replace(/\n/g, '<br>');

  const wrappedHtml = '<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;font-size:14px;color:#333;">'
    + '<p style="margin:0 0 12px;">' + htmlDraft + '</p>'
    + SIGNATURE_HTML
