const items = $input.all();
const mergeItems = $('Merge Enriched + Thread Meta').all();
const results = [];
const MAX_SIZE = 4000000;
const ALLOWED = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];

for (let i = 0; i < items.length; i++) {
  const msg = items[i].json;
  const prev = mergeItems[i]?.json || {};
  let attId = null, mime = null, inlineB64 = null;

  function scan(parts) {
    if (!parts || attId || inlineB64) return;
    for (const p of parts) {
      if (p.mimeType && ALLOWED.includes(p.mimeType) && (p.body?.size || 0) < MAX_SIZE) {
        mime = p.mimeType;
        if (p.body?.data) { inlineB64 = p.body.data; return; }
        if (p.body?.attachmentId) { attId = p.body.attachmentId; return; }
      }
      if (p.parts) scan(p.parts);
    }
  }

  const pl = msg.payload;
  if (pl?.parts) scan(pl.parts);
  else if (pl && ALLOWED.includes(pl.mimeType) && pl.body) {
    mime = pl.mimeType;
    if (pl.body.data) inlineB64 = pl.body.data;
    else if (pl.body.attachmentId) attId = pl.body.attachmentId;
  }

  results.push({ json: {
    ...prev,
    _has_image: !!(attId || inlineB64),
    _needs_dl: !!attId,
    _att_id: attId,
    _img_mime: mime,
    _img_inline: inlineB64
  }});
}
return results;

